"""Escalation worker for processing overdue incidents."""

from __future__ import annotations

from .models import Incident
from .sqlite_store import SQLiteIncidentStore


class EscalationWorker:
    def __init__(self, store: SQLiteIncidentStore, worker_id: str) -> None:
        self.store = store
        self.worker_id = worker_id

    def run_once(self, now: float | None = None) -> Incident | None:
        """Claim and complete one overdue escalation."""
        self.store.recover_expired_claims(now=now)

        incident = self.store.claim_due_escalation(self.worker_id, now=now)
        if not incident:
            return None

        return self.store.complete_escalation(incident.id, self.worker_id, now=now)

    def run_until_idle(
        self, max_incidents: int | None = None, now: float | None = None
    ) -> list[Incident]:
        """Process escalations until no more are due."""
        completed = []
        count = 0

        while True:
            if max_incidents is not None and count >= max_incidents:
                break

            incident = self.run_once(now=now)
            if incident is None:
                break

            completed.append(incident)
            count += 1

        return completed

