    method: "POST",
    headers: {"Content-Type": "application/json"},
    body: JSON.stringify(Object.fromEntries(data)),
  });
  feedback.textContent = response.ok ? "Incident created" : "Could not create incident";
  if (response.ok) {
    form.reset();
    await refresh();
  }
});

