  const ownerInput = `<input data-testid="owner-input" type="text" value="${escapeHtml(incident.owner || "")}" placeholder="Assign owner">`;

  const acknowledgeBtn = incident.status === "open" 
    ? `<button data-testid="acknowledge-action" class="action-btn">Acknowledge</button>`
    : "";

  const resolveBtn = incident.status !== "resolved"
    ? `<button data-testid="resolve-action" class="action-btn">Resolve</button>`
    : "";

  incidentDetailEl.innerHTML = `
    <div class="detail-header">
      <h3>${escapeHtml(incident.title)}</h3>
      <span class="severity severity-${incident.severity}">${incident.severity}</span>
      <span class="status status-${incident.status}">${incident.status}</span>
    </div>

    <div class="detail-info">
      <div><strong>ID:</strong> ${incident.id}</div>
      <div><strong>Fingerprint:</strong> ${escapeHtml(incident.fingerprint)}</div>
      <div><strong>Version:</strong> ${incident.version}</div>
      <div><strong>Alert Count:</strong> ${incident.alert_count}</div>
      <div><strong>Escalation Level:</strong> ${incident.escalation_level}</div>
      <div><strong>Created:</strong> ${formatTimestamp(incident.created_at)}</div>
      <div><strong>Updated:</strong> ${formatTimestamp(incident.updated_at)}</div>
      <div><strong>SLA Deadline:</strong> ${formatTimestamp(incident.sla_deadline)}</div>
    </div>

    <div class="detail-actions">
      <label>
        <strong>Owner:</strong>
        ${ownerInput}
      </label>
      ${acknowledgeBtn}
      ${resolveBtn}
    </div>

    <div data-testid="timeline" class="timeline">
      <h4>Timeline</h4>
      <div class="events"></div>
    </div>
  `;

  const ownerInputEl = incidentDetailEl.querySelector("[data-testid='owner-input']");
  if (ownerInputEl) {
    ownerInputEl.addEventListener("change", async (e) => {
      await updateIncident(incident.id, incident.version, { owner: e.target.value });
    });
  }

  const acknowledgeBtn = incidentDetailEl.querySelector("[data-testid='acknowledge-action']");
  if (acknowledgeBtn) {
    acknowledgeBtn.addEventListener("click", async () => {
      await updateIncident(incident.id, incident.version, { status: "acknowledged" });
    });
  }

  const resolveBtn = incidentDetailEl.querySelector("[data-testid='resolve-action']");
  if (resolveBtn) {
    resolveBtn.addEventListener("click", async () => {
      await updateIncident(incident.id, incident.version, { status: "resolved" });
    });
  }

  renderTimeline(incident.events || []);
}

function renderTimeline(events) {
  const eventsEl = incidentDetailEl.querySelector(".events");
  if (!eventsEl) return;

  if (events.length === 0) {
    eventsEl.innerHTML = "<p>No events</p>";
    return;
  }

  eventsEl.innerHTML = "";
  events.forEach((event) => {
    const eventEl = document.createElement("div");
    eventEl.className = "event";
    eventEl.innerHTML = `
      <div class="event-type">${event.type}</div>
      <div class="event-time">${formatTimestamp(event.timestamp)}</div>
      <div class="event-details">${JSON.stringify(event.details)}</div>
    `;
    eventsEl.appendChild(eventEl);
  });
}

async function updateIncident(incidentId, expectedVersion, updates) {
  try {
    const response = await fetch(`/api/incidents/${incidentId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        expected_version: expectedVersion,
        ...updates,
      }),
    });

    if (response.status === 409) {
      showFeedback("Conflict: Incident was updated by someone else. Refreshing...", "error");
      await refresh();
      return;
    }

    if (!response.ok) {
      const error = await response.json();
      showFeedback(`Update failed: ${error.error}`, "error");
      return;
    }

    showFeedback("Incident updated successfully", "success");
    await refresh();
  } catch (error) {
    showFeedback(`Error updating incident: ${error.message}`, "error");
  }
}

function showFeedback(message, type = "info") {
  state.feedback = message;
  feedbackEl.textContent = message;
  feedbackEl.className = `feedback ${type}`;

  setTimeout(() => {
    feedbackEl.textContent = "";
    feedbackEl.className = "feedback";
    state.feedback = "";
  }, 5000);
}

function escapeHtml(text) {
  const div = document.createElement("div");
  div.textContent = text;
  return div.innerHTML;
}

function formatTimestamp(timestamp) {
  return new Date(timestamp * 1000).toLocaleString();
}

statusFilter.addEventListener("change", (e) => {
  state.filters.status = e.target.value;
  refresh();
});

severityFilter.addEventListener("change", (e) => {
  state.filters.severity = e.target.value;
  refresh();
});

window.incidentOps = {
  refresh,
  selectIncident,
  getState: () => ({
    filters: { ...state.filters },
    selectedIncidentId: state.selectedIncidentId,
    incidents: [...state.incidents],
    feedback: state.feedback,
  }),
};

