  border-bottom: 1px solid var(--border-color);
  padding: 12px 16px;
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.filters label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 600;
}

.filters select {
