.feedback {
  padding: 12px 16px;
  margin: 0;
  font-size: 13px;
  min-height: 18px;
}

.feedback.success {
  background: var(--success);
  color: white;
}

.feedback.error {
  background: var(--error);
  color: white;
}

.container {
  display: flex;
  height: calc(100vh - 200px);
  min-height: 400px;
}

.incident-list-panel {
  flex: 0 0 50%;
  border-right: 1px solid var(--border-color);
  background: var(--bg-secondary);
  overflow-y: auto;
  overflow-x: hidden;
}

.incident-list-panel h2 {
  margin: 0;
  padding: 16px;
  font-size: 16px;
  border-bottom: 1px solid var(--border-color);
