.incident-row.selected {
  background: var(--accent);
  color: white;
  border-color: var(--accent);
}

.incident-row-header {
  display: flex;
  gap: 8px;
  margin-bottom: 8px;
}

.incident-row-title {
  font-weight: 600;
  margin-bottom: 6px;
  font-size: 14px;
}

.incident-row-meta {
  font-size: 12px;
  opacity: 0.8;
