.status-open {
  background: var(--error);
  color: white;
}

.status-acknowledged {
  background: var(--warning);
  color: white;
}

.status-resolved {
  background: var(--success);
  color: white;
}

.detail-panel {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  background: var(--bg-secondary);
}

.incident-detail {
  padding: 16px;
