  display: inline-block;
  min-width: 130px;
}

.detail-actions {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 16px;
  padding: 12px;
  background: var(--bg-primary);
  border-radius: 6px;
}

.detail-actions label {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.detail-actions input {
  padding: 8px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  font: inherit;
  width: 100%;
}

.action-btn {
  padding: 10px 16px;
