}

.action-btn:hover {
  background: #264087;
}

.timeline {
  margin-top: 16px;
}

.timeline h4 {
  margin: 0 0 12px 0;
  font-size: 16px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--border-color);
}

.events {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.event {
  padding: 12px;
  background: var(--bg-primary);
  border-radius: 6px;
  font-size: 13px;
  word-wrap: break-word;
  overflow-wrap: break-word;
}

.event-type {
  font-weight: 600;
  margin-bottom: 4px;
  color: var(--accent);
}

.event-time {
  font-size: 12px;
  color: var(--text-secondary);
  margin-bottom: 4px;
}

.event-details {
  font-family: monospace;
  font-size: 12px;
  white-space: pre-wrap;
  word-break: break-all;
}

@media (max-width: 768px) {
  .container {
    flex-direction: column;
    height: auto;
  }

  .incident-list-panel {
    flex: none;
    border-right: none;
    border-bottom: 1px solid var(--border-color);
    max-height: 50vh;
  }

  .detail-panel {
    flex: none;
  }

  .detail-info strong {
    min-width: 100px;
  }
}

@media (max-width: 390px) {
  header {
    padding: 12px;
