    font-size: 18px;
  }

  .filters {
    padding: 8px 12px;
    gap: 12px;
  }

  .filters label {
    font-size: 12px;
  }

  .incident-list-panel h2 {
    font-size: 14px;
    padding: 12px;
  }

  .incident-row {
    padding: 10px;
  }

  .incident-detail {
    padding: 12px;
  }

  .detail-header h3 {
    font-size: 16px;
  }

