observation.new_content:
:root {
  --bg-primary: #eef2f7;
  --bg-secondary: white;
  --border-color: #d8e0ea;
  --text-primary: #172033;
  --text-secondary: #5a6c7d;
  --accent: #3154a5;
  --error: #d32f2f;
  --success: #2e7d32;
  --warning: #f57c00;
  --p1-color: #d32f2f;
  --p2-color: #f57c00;
  --p3-color: #fbc02d;
  --p4-color: #388e3c;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  color: var(--text-primary);
  background: var(--bg-primary);
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 14px;
  line-height: 1.5;
}

[data-testid="incident-app"] {
  max-width: 100vw;
  overflow-x: hidden;
}

header {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  padding: 16px;
}

header h1 {
  margin: 0 0 12px 0;
  font-size: 20px;
  font-weight: 700;
}

.summary {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 13px;
  color: var(--text-secondary);
}

.filters {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  padding: 12px 16px;
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.filters label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 600;
}

.filters select {
  padding: 6px 8px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  font: inherit;
  background: white;
}

.feedback {
  padding: 12px 16px;
  margin: 0;
  font-size: 13px;
  min-height: 18px;
}

.feedback.success {
  background: var(--success);
  color: white;
}

.feedback.error {
  background: var(--error);
  color: white;
}

.container {
  display: flex;
  height: calc(100vh - 200px);
  min-height: 400px;
}

.incident-list-panel {
  flex: 0 0 50%;
  border-right: 1px solid var(--border-color);
  background: var(--bg-secondary);
  overflow-y: auto;
  overflow-x: hidden;
}

.incident-list-panel h2 {
  margin: 0;
  padding: 16px;
  font-size: 16px;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-primary);
  position: sticky;
  top: 0;
  z-index: 1;
}

.incident-list {
  padding: 8px;
}

.incident-row {
  padding: 12px;
  margin-bottom: 8px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s;
  word-wrap: break-word;
  overflow-wrap: break-word;
}

.incident-row:hover {
  background: var(--bg-primary);
  border-color: var(--accent);
}

.incident-row.selected {
  background: var(--accent);
  color: white;
  border-color: var(--accent);
}

.incident-row-header {
  display: flex;
  gap: 8px;
  margin-bottom: 8px;
}

.incident-row-title {
  font-weight: 600;
  margin-bottom: 6px;
  font-size: 14px;
}

.incident-row-meta {
  font-size: 12px;
  opacity: 0.8;
}

.severity, .status {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.severity-P1 {
  background: var(--p1-color);
  color: white;
}

.severity-P2 {
  background: var(--p2-color);
  color: white;
}

.severity-P3 {
  background: var(--p3-color);
  color: #000;
}

.severity-P4 {
  background: var(--p4-color);
  color: white;
}

.status-open {
  background: var(--error);
  color: white;
}

.status-acknowledged {
  background: var(--warning);
  color: white;
}

.status-resolved {
  background: var(--success);
  color: white;
}

.detail-panel {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  background: var(--bg-secondary);
}

.incident-detail {
  padding: 16px;
  max-width: 100%;
}

.incident-detail .placeholder {
  color: var(--text-secondary);
  text-align: center;
  padding: 40px 16px;
}

.detail-header {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: 16px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border-color);
}

.detail-header h3 {
  margin: 0;
  font-size: 18px;
  flex: 1 1 100%;
  word-wrap: break-word;
}

.detail-info {
  display: grid;
  gap: 8px;
  margin-bottom: 16px;
  padding: 12px;
  background: var(--bg-primary);
  border-radius: 6px;
  font-size: 13px;
  word-wrap: break-word;
}

.detail-info strong {
  display: inline-block;
  min-width: 130px;
}

.detail-actions {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 16px;
  padding: 12px;
  background: var(--bg-primary);
  border-radius: 6px;
}

.detail-actions label {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.detail-actions input {
  padding: 8px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  font: inherit;
  width: 100%;
}

.action-btn {
  padding: 10px 16px;
  border: none;
  border-radius: 6px;
  background: var(--accent);
  color: white;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
}

.action-btn:hover {
  background: #264087;
}

.timeline {
  margin-top: 16px;
}

.timeline h4 {
  margin: 0 0 12px 0;
  font-size: 16px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--border-color);
}

.events {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.event {
  padding: 12px;
  background: var(--bg-primary);
  border-radius: 6px;
  font-size: 13px;
  word-wrap: break-word;
  overflow-wrap: break-word;
}

.event-type {
  font-weight: 600;
  margin-bottom: 4px;
  color: var(--accent);
}

.event-time {
  font-size: 12px;
  color: var(--text-secondary);
  margin-bottom: 4px;
}

.event-details {
  font-family: monospace;
  font-size: 12px;
  white-space: pre-wrap;
  word-break: break-all;
}

@media (max-width: 768px) {
  .container {
    flex-direction: column;
    height: auto;
  }

  .incident-list-panel {
    flex: none;
    border-right: none;
    border-bottom: 1px solid var(--border-color);
    max-height: 50vh;
  }

  .detail-panel {
    flex: none;
  }

  .detail-info strong {
    min-width: 100px;
  }
}

@media (max-width: 390px) {
  header {
    padding: 12px;
  }

  header h1 {
    font-size: 18px;
  }

  .filters {
    padding: 8px 12px;
    gap: 12px;
  }

  .filters label {
    font-size: 12px;
  }

  .incident-list-panel h2 {
    font-size: 14px;
    padding: 12px;
  }

  .incident-row {
    padding: 10px;
  }

  .incident-detail {
    padding: 12px;
  }

  .detail-header h3 {
    font-size: 16px;
  }

  .detail-info strong {
    min-width: 90px;
    font-size: 12px;
  }
}

